const aggregates = $('Supabase - Fetch Aggregated Data').all().map(i => i.json);
const categories = $('Supabase - Category Breakdown').all().map(i => i.json);
const trends = $('Supabase - Monthly Trend Data').all().map(i => i.json);

// Compute simple linear regression for trend prediction
function linearRegression(data) {
  const n = data.length;
  if (n < 2) return { slope: 0, intercept: data[0]?.monthly_total || 0, r2: 0 };

  const xVals = data.map((_, i) => i);
  const yVals = data.map(d => parseFloat(d.monthly_total) || 0);

  const xMean = xVals.reduce((a, b) => a + b, 0) / n;
  const yMean = yVals.reduce((a, b) => a + b, 0) / n;

  const numerator = xVals.reduce((sum, x, i) => sum + (x - xMean) * (yVals[i] - yMean), 0);
  const denominator = xVals.reduce((sum, x) => sum + Math.pow(x - xMean, 2), 0);

  const slope = denominator !== 0 ? numerator / denominator : 0;
  const intercept = yMean - slope * xMean;

  const ssRes = yVals.reduce((sum, y, i) => sum + Math.pow(y - (slope * i + intercept), 2), 0);
  const ssTot = yVals.reduce((sum, y) => sum + Math.pow(y - yMean, 2), 0);
  const r2 = ssTot !== 0 ? 1 - ssRes / ssTot : 1;

  return { slope: Math.round(slope * 100) / 100, intercept: Math.round(intercept * 100) / 100, r2: Math.round(r2 * 1000) / 1000 };
}

const regression = linearRegression(trends);
const nextMonthPrediction = regression.slope * trends.length + regression.intercept;
const twoMonthPrediction = regression.slope * (trends.length + 1) + regression.intercept;

// Detect anomalies (values > 2 std deviations from mean)
const amounts = categories.map(c => parseFloat(c.total_amount) || 0);
const mean = amounts.reduce((a, b) => a + b, 0) / (amounts.length || 1);
const stddev = Math.sqrt(amounts.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / (amounts.length || 1));
const anomalies = categories.filter(c => Math.abs(parseFloat(c.total_amount) - mean) > 2 * stddev);

// Month-over-month trend direction
const latestTrend = trends[trends.length - 1];
const trendDirection = latestTrend?.month_over_month_pct_change > 0 ? 'upward' :
  latestTrend?.month_over_month_pct_change < 0 ? 'downward' : 'stable';

return [{
  json: {
    aggregates,
    categories,
    trends,
    analysis: {
      totalTransactions: aggregates.reduce((sum, r) => sum + parseInt(r.transaction_count || 0), 0),
      totalAmount: Math.round(aggregates.reduce((sum, r) => sum + parseFloat(r.total_amount || 0), 0) * 100) / 100,
      topCategory: categories[0]?.category || 'N/A',
      topCategoryAmount: categories[0]?.total_amount || 0,
      trendDirection,
      latestMonthGrowth: latestTrend?.month_over_month_pct_change || 0,
      anomalies: anomalies.map(a => ({ category: a.category, amount: a.total_amount })),
      regression,
      predictions: {
        nextMonth: Math.round(nextMonthPrediction * 100) / 100,
        twoMonthsOut: Math.round(twoMonthPrediction * 100) / 100
      }
    }
  }
}];

